
  create table "public"."crossings" (
    "id" bigint generated by default as identity not null,
    "created_at" timestamp with time zone not null default now(),
    "fra_crossing_id" character varying not null,
    "street" text
      );


alter table "public"."crossings" enable row level security;

alter table "public"."detections" add column "crossing_id" bigint not null default '1'::bigint;

CREATE UNIQUE INDEX crossings_fra_crossing_id_key ON public.crossings USING btree (fra_crossing_id);

CREATE UNIQUE INDEX crossings_pkey ON public.crossings USING btree (id);

alter table "public"."crossings" add constraint "crossings_pkey" PRIMARY KEY using index "crossings_pkey";

alter table "public"."crossings" add constraint "crossings_fra_crossing_id_key" UNIQUE using index "crossings_fra_crossing_id_key";

alter table "public"."detections" add constraint "detections_crossing_id_fkey" FOREIGN KEY (crossing_id) REFERENCES public.crossings(id) not valid;

alter table "public"."detections" validate constraint "detections_crossing_id_fkey";

grant references on table "public"."crossings" to "anon";

grant trigger on table "public"."crossings" to "anon";

grant truncate on table "public"."crossings" to "anon";

grant references on table "public"."crossings" to "authenticated";

grant trigger on table "public"."crossings" to "authenticated";

grant truncate on table "public"."crossings" to "authenticated";

grant references on table "public"."crossings" to "service_role";

grant trigger on table "public"."crossings" to "service_role";

grant truncate on table "public"."crossings" to "service_role";


